import hashlib
h = lambda b: hashlib.sha256(b).digest()

def merkle_root(blocks):
    level = [h(b'\x00' + b) for b in blocks]
    while len(level) > 1:
        if len(level) % 2: level.append(level[-1])
        level = [h(b'\x01' + level[i] + level[i+1]) for i in range(0, len(level), 2)]
    return level[0]

def verify(leaf, path, root):
    node = h(b'\x00' + leaf)
    for sibling, is_left in path:
        node = h(b'\x01' + (sibling + node if is_left else node + sibling))
    return node == root
